INSERT INTO `mod_lore_codex_entry` (`ID`, `Kind`, `Zone`, `SortOrder`, `Faction`, `RequiredState`, `Title`, `Body`, `Sources`) VALUES
(343300, 0, 3433, 0, 0, 0, 'Ghostlands', 'South of the Elrendar River, the forests of Quel''Thalas give way to the Ghostlands, a country that never recovered from the Third War. When Arthas led the Scourge north toward Silvermoon and the Sunwell, his host left a blighted trail of death behind it, and that trail, the Dead Scar, still runs from the citadel of Deatholme across the heart of the region. The survivors of that onslaught named the ruined land the Ghostlands, and the name has proven all too apt. Ghosts haunt the abandoned villages, plague runs in the blood of lynx, bat and spider, and even the murlocs of the coast walk in undeath. From Deatholme the traitor Dar''Khan Drathir commands what remains of the Scourge. Against him stand the blood elves of Tranquillien, aided by Forsaken soldiers sent by Lady Sylvanas Windrunner, the magisters of the Sanctum of the Sun and the Farstriders of Lake Elrendar. To the east, Shadowpine trolls of the Amani hold the forest along the road to Zul''Aman.', 'warcraft.wiki.gg/wiki/Ghostlands (named by survivors of the Third War onslaught; Elrendar River border; Amani and Zul''Aman; Tranquillien, Farstrider Enclave, Sanctum of the Sun strongholds); quest 9155 description (Scourge follow Arthas''s path to Silvermoon); quests 9147, 9158, 9159 (plagued wildlife south of the river); quest 9149 description (murlocs retained free will in undeath); quest 9327 reward text (Forsaken here against Dar''Khan, Sylvanas); gossip 16463 (Shadowpine backed by the might of Zul''Aman)'),
(343301, 1, 3433, 1, 0, 0, 'Tranquillien', 'Tranquillien was a high elven town until the fall of Quel''Thalas, when its people abandoned it and retreated to Silvermoon. Now it is the blood elves'' foothold in the Ghostlands, ringed by enemies and short of nearly everything. Dame Auriferous governs the town, while Forsaken soldiers under High Executor Mavren hold the tower on its western side, a sight that still unsettles some of the sin''dorei. Dragonhawks carry supplies down from Silvermoon, where even the merchants admit that the Forsaken have put their backs to the wall for the elves, and a trader in town grumbles about an escort that never came. From here the campaign against Dar''Khan is planned, argued over and launched.', 'warcraft.wiki.gg/wiki/Tranquillien (high elves abandoned it and retreated to Silvermoon in the Third War; Forsaken under Mavren; Dame Auriferous leads); quest 9327 description (Mavren in the tower on the west side of town); quests 9130, 9133, 9135 (supplies by dragonhawk; Forsaken have put their backs to the wall for us); quest 9152 description (escort that never came); gossip 16253 Master Chef Mouldier (disgusting Forsaken around here); zone_areas: Mavren, Auriferous, Skymaster Sunwing, Ghostlands Guardians in area 3488; quest 9135 starter Sathren Azuredawn in Silvermoon; quest 9133 reward text (Lymel''s rotting brain)'),
(343302, 1, 3433, 2, 0, 0, 'Goldenmist Village', 'Goldenmist Village lies in the northwest of the Ghostlands, reached by the western road out of Tranquillien. It was a high elven village until the Scourge came, and its people never truly left: the elves who died there returned as ghosts and wraiths that still drift through the empty houses, a gruesome tactic the Scourge seems to favor. Freeing it was the second step in Tranquillien''s campaign to break the Scourge hold on the outlying villages. Atop its central building is a rune of summoning, where young warlocks of Silvermoon are sent to call forth a voidwalker and defeat it before returning to their teachers.', 'quest 9139 description and reward text (northwest, west road, ghosts of the high elves who lived there, Scourge tactics); warcraft.wiki.gg/wiki/Goldenmist_Village (high elven village; elves who died there returned as ghosts); quest 9619 description (rune of summoning atop the center building, voidwalker; blood elf warlocks only); zone_areas: Quel''dorei Ghost 16325 and Quel''dorei Wraith 16326 in area 3490'),
(343303, 1, 3433, 3, 0, 0, 'Sanctum of the Moon', 'West of Tranquillien stand the remains of the Sanctum of the Moon, an arcane sanctum of old Quel''Thalas. While the magisters pour their effort into the rebuilt Sanctum of the Sun, this one has been all but forgotten. Little of the structure survives, and the energies that still linger in it have given rise to bizarre creatures: arcane devourers and mana shifters that feed among the ruins. Magister Darenis of Tranquillien, who hates to see good resources go to waste, wants the crystallized mana essences these creatures carry, and he finds them remarkably powerful.', 'quest 9150 description, log text and reward text; zone_areas: Arcane Devourer 16304 and Mana Shifter 16310 in area 3494'),
(343304, 1, 3433, 4, 0, 0, 'Suncrown Village', 'In the northeastern Ghostlands, west of Lake Elrendar, lie the ruins of Suncrown Village. Its people once held a yearly rite to keep the forces of nature under their control, and dominion over water was symbolized by summoning and binding an elemental called Aquantion. The rite ended in disaster, and the drowned villagers haunt the lake still. Since the Scourge invasion, nerubians have claimed the village. Their guards swarm its broken streets under a leader named Anok''suten, whose presence none of Tranquillien''s scouts reported, and at least one blood elf sent to clear the village now lies dying for that oversight.', 'quest 9157 description and request text (yearly ritual, Aquantion, the drowned still haunt this lake); quest 9174 description (lake east of Suncrown Village); quest 9138 description (Nerubian Scourge at Suncrown); quest 9315 description, request and reward text (Anok''suten; no scouting mission reported it; dying blood elf); warcraft.wiki.gg/wiki/Suncrown_Village (destroyed in the Scourge invasion, nerubians led by Anok''suten); zone_areas: Nerubis Guard x45 and Anok''suten 16357 in area 3489'),
(343305, 1, 3433, 5, 0, 0, 'Lake Elrendar', 'Lake Elrendar spreads across the northeast of the Ghostlands, not far from the Elrendar River that divides this land from Eversong. Its waters offer no refuge. Vengeful and ravening apparitions drift over the surface, the spirits of elves who drowned there in a tragedy whose details are now mostly forgotten, and on the lake bed lies the Altar of Tidal Mastery, where the people of Suncrown once bound the elemental Aquantion. On the western shore the survivors of a failed Farstrider attack on the trolls across the water nurse their wounds, while the Farstrider Enclave keeps watch from the southern bank.', 'quest 9274 description (ancestors drowned at the bottom of the lake; details mostly forgotten); quests 9157, 9174 (Altar of Tidal Mastery at the bottom of the lake); quests 9143, 9145 (failed attack across the lake; Valanna and Tomathren on the shore of Lake Elrendar); quest 9146 description (Farstrider Enclave on the south edge of the lake); warcraft.wiki.gg/wiki/Ghostlands (Elrendar River separated the forest from the northern woodland); zone_areas: Vengeful/Ravening Apparition 16328/16327 and gameobject 181157 in area 3513'),
(343306, 1, 3433, 6, 0, 0, 'Dawnstar Spire', 'On the eastern shore of Lake Elrendar rises Dawnstar Spire, the tower where Dar''Khan Drathir spent much of his time, passing many nights there scheming against his own people. Arcane reavers now guard its halls. Among the dust inside lay his journal, its pages full of hatred and contempt for the elves and of plots recorded in careful detail, his scheme to steal the power of the Sunwell for the Scourge among them. Whoever turns those pages is gripped by an unnerving sense of being watched.', 'warcraft.wiki.gg/wiki/Dawnstar_Spire (eastern shore of Lake Elrendar; guarded by Arcane Reavers); spawn coordinates east of the lake; quest 9161 description (spent many nights there scheming against his own); quest 9162 description and reward text (journal, hatred and contempt, sense of being watched, plan to steal the Sunwell''s power); gameobject 181150 Dusty Journal starts quest 9162; zone_areas: Arcane Reaver 16339 x11 and the journal in area 3495'),
(343307, 1, 3433, 7, 0, 0, 'Farstrider Enclave', 'The Farstrider Enclave stands on the southern shore of Lake Elrendar, cut off from the other blood elf holdings and hemmed in by haunted water to the north and Shadowpine trolls to the east and south. Captain Helios commands the rangers here, and they have spent their strength keeping the trolls off balance rather than marching on Deatholme, a choice the Forsaken commander in Tranquillien calls senseless skirmishing. An apothecary on loan from Tranquillien brews poisons for the trolls'' food, and a wanted poster offers a reward for the head of Kel''gash the Wicked, chieftain of the Shadowpine.', 'warcraft.wiki.gg/wiki/Farstrider_Enclave (southern shore, cut off, surrounded by lake ghosts and Shadowpine trolls to east and south; Captain Helios); quest 9276 description (keeping the trolls off balance); creature_text 16252 (pull the Farstriders from their senseless skirmishing with the trolls); quest 9275 description and reward text (Apothecary Venustus on loan, poison); gameobject 181153 Wanted Poster: Kel''gash the Wicked starts quest 9215; zone_areas: Helios, Venustus and the poster stand in area 3513 just outside 3496; Vynna, Sedina in 3496'),
(343308, 1, 3433, 8, 0, 0, 'The Shadowpine Villages', 'The Shadowpine, a forest troll tribe of the Amani, hold three camps in the eastern Ghostlands. Zeb''Sora lies on the far shore of Lake Elrendar, where a Farstrider attack ended in slaughter. Zeb''Tela, east of the Farstrider Enclave, shelters headhunters and shadowcasters, and Zeb''Nowa to the south straddles both sides of the road to Zul''Aman and is home to the tribe''s catlords and hexxers. Their chieftain, Kel''gash the Wicked, dwells there among racks of drying meat and fish. Backed by the might of Zul''Aman, these camps keep the Farstriders from turning their full strength against the Scourge.', 'warcraft.wiki.gg/wiki/Shadowpine_tribe (forest troll tribe of the Amani; Zeb''Sora, Zeb''Nowa, Zeb''Tela); quests 9143, 9145 (Zeb''Sora across Lake Elrendar, Farstriders decimated); quests 9214, 9276, 9277 (Zeb''Tela east, Zeb''Nowa south; headhunters, shadowcasters, catlords, hexxers); quest 9275 description (Zeb''Nowa straddles the road to Zul''Aman); quest 9215 (Kel''gash dwells in Zeb''Nowa); zone_areas: Kel''gash 16358 and meat and fish racks in area 3517; gossip 16463 (Shadowpine trolls backed by the might of Zul''Aman)'),
(343309, 1, 3433, 9, 0, 0, 'The Dead Scar', 'The Dead Scar is the trail of ruin Arthas Menethil left across Quel''Thalas as he marched on Silvermoon and the Sunwell. Beginning at Deatholme, it runs north through the heart of the Ghostlands and over the river into Eversong, a ribbon of blighted, lifeless ground. Mindless Scourge still follow it to this day: risen hungerers, gangled cannibals and dreadbone skeletons wander its length, and the abomination Luzran stalks among them. Two Scourge ziggurats rise in the middle of the Scar. Even the roads that cross it are dangerous; the trader Rathis Tomber lost a supply cart to ghouls just beyond it on his way to Tranquillien.', 'quest 9155 description (mindless Scourge follow the path of destruction Arthas created on his way to Silvermoon); warcraft.wiki.gg/wiki/Dead_Scar (began at Deatholme, crossed the Elrendar River into Eversong, ended at the Sunwell); quest 9176 description (ziggurats in the middle of the Dead Scar); quest 9152 description (cart left behind beyond the Dead Scar after a ghoul attack); zone_areas: Risen Hungerer, Gangled Cannibal, Dreadbone Skeleton, Luzran 16245 in area 3514'),
(343310, 1, 3433, 10, 0, 0, 'An''daroth, An''telas and An''owyn', 'Three old ley-line nexuses of the high elves lie scattered across the Ghostlands: An''daroth to the northwest beyond the Dead Scar, An''telas on the southern slopes of Sungraze Peak, and the remote An''owyn far to the south. Their power has drawn night elf agents, who have raised moon crystals at the sites, scrying devices meant to spy on the sin''dorei. Sentinel spies hold An''daroth and infiltrators guard An''owyn. At An''telas, where Magister Sylastor studies the nexus energy for use against the Scourge, the bodies of a night elf party lie where his scouts and casters cut them down.', 'quest 9160 description (An''daroth, old high elf ley-line nexus, northwest past the Dead Scar); quest 9163 reward text (An''owyn a more remote nexus; third nexus An''telas); quest 9166 description and reward text (An''telas on the southern slopes of Sungraze Peak; Sylastor''s studies; night elves killed by scouts and casters); quest 9169 description (moon crystals are scrying devices; An''owyn directly to the south; power); zone_areas: Sentinel Spy 16330 in 3497, Sentinel Infiltrator 16333 in 3499, Night Elf Corpse 16804 and Sylastor in 3498, Night Elf Moon Crystal gameobjects'),
(343311, 1, 3433, 11, 0, 0, 'Sanctum of the Sun', 'Southeast of Tranquillien, just south of Sungraze Peak, the magisters have rebuilt an old arcane sanctum and put it back in working order. The Sanctum of the Sun is a banner of defiance raised before Dar''Khan''s seat of power, and some of Silvermoon''s most powerful magisters have come to run it under Magister Kaendris. Here they study the Scourge''s weaknesses with the help of the Forsaken and prepare the assault on Deatholme. Patience runs thin. Magister Idonis chafes at every delay, while Arcanist Janeda reminds him that working sanctums are rare, and that once this one runs at full capacity Silvermoon will have to send help.', 'quests 9150, 9151 descriptions (functioning arcane sanctum southeast of Tranquillien; powerful magisters from Silvermoon rebuilt it); quest 9207 description (just south of Sungraze Peak); quest 9220 description (banner of defiance in front of Deatholme); quest 9172 description (progress analyzing the Scourge''s weaknesses with the Forsaken); creature_text 16204 and 16240 (Idonis impatient; functioning sanctums in short supply); warcraft.wiki.gg/wiki/Sanctum_of_the_Sun (Kaendris leads)'),
(343312, 1, 3433, 12, 0, 0, 'Sungraze Peak and the Amani Catacombs', 'Sungraze Peak rises east of Tranquillien, and within it lie the Amani Catacombs, where the forest trolls laid their dead to rest. The dead do not rest there now. Mummified headhunters have begun to rise and walk the tunnels, raised by Shadowpine oracles with glowing juju, it seems to bolster the tribe''s numbers, and Tranquillien wants the remains that have not yet stirred put to the torch. The trolls use the catacombs for captives as well. A Farstrider, Ranger Lilatha, was ambushed and locked in a cage there, certain that her captors meant to sacrifice her.', 'quest 9193 description (trolls buried in the Amani Catacombs inside Sungraze Peak rising; burn the unanimated remains); quest 9199 description and reward text (juju; Shadowpine bolstering their numbers; oracles using it); quest 9212 description (Lilatha ambushed and caged, planning to sacrifice me); zone_areas: Mummified Headhunter, Shadowpine Oracle, Mummified Troll Remains in areas 3509 and 3510; Ranger Lilatha 16295 and Cage 181152 in 3509'),
(343313, 1, 3433, 13, 0, 0, 'Underlight Mines', 'The Underlight Mines lie southwest of Tranquillien, reached by a short dirt track off the southern road just past one of the ziggurats. Their ore is a strategic asset in the campaign, for the armor and weapons the defenders need must first be dug from the ground. A clan of gnolls calling themselves the Blackpaw has overrun the tunnels and driven the miners out. Apprentice Shatharia, sent from the Sanctum of the Sun to gather tin and copper samples for an experiment against the Scourge, waits at the entrance wondering how she is to finish her errand with gnoll vermin everywhere.', 'quest 9192 description and reward text (southwest, dirt path past the ziggurat, Blackpaw clan, strategic asset, ore for armor and weaponry); quest 9207 description and reward text (Shatharia sent from the Sanctum of the Sun, tin and copper veins, help in the fight against the Scourge); gossip 16293 (overrun with gnoll vermin); zone_areas: Blackpaw Gnoll, Scavenger, Shaman and Apprentice Shatharia in area 3505'),
(343314, 1, 3433, 14, 0, 0, 'The Twin Ziggurats', 'In the middle of the Dead Scar stand the Bleeding Ziggurat and the Howling Ziggurat, twin Scourge structures held by darkmages and stonewing trackers. Dar''Khan''s own journal reveals why they matter. He promised his masters two elven artifacts, the stone of light and the stone of flame, charged with the energies of the Sunwell and attuned to ward against the Scourge, and the stones were to be carried to the very ground where the ziggurats now stand. The abomination Knucklerot patrols near the Howling Ziggurat, and Tranquillien has posted a bounty for his head and that of his fellow abomination, Luzran.', 'quest 9176 description (stones of light and flame, Sunwell energies, warding powers, transported to where the ziggurats now stand in the middle of the Dead Scar); quest 9156 description (bounty on Knucklerot and Luzran, patrolling near the Howling and Bleeding Ziggurats); gameobject 181147 Wanted Poster in Tranquillien starts quest 9156; zone_areas: Deatholme Darkmage 16318 and Stonewing Tracker 16316 in 3501 and 3502; Knucklerot 16246 in 3502'),
(343315, 1, 3433, 15, 0, 0, 'Windrunner Village', 'Windrunner Village, in the southwest of the Ghostlands, was the last and hardest of the three outlying villages Tranquillien set out to reclaim. Here the Scourge posted not mindless dead but its stronger shock troops: phantasmal shades drifting among the houses and stonewing gargoyles stalking the lanes. The magisters of the Sanctum of the Sun have taken a keen interest in their remains, hoping that study of them will reveal new ways of fighting the Scourge. Nearby stands Windrunner Spire, the ancestral home of the family that gave Quel''Thalas its most famous rangers.', 'quest 9140 description and reward text (southwest, shades and gargoyles, magisters want remains, third village); warcraft.wiki.gg/wiki/Windrunner_Spire (home of the Windrunner family near Windrunner Village); zone_areas: Phantasmal Seeker 16323 and Stonewing Slayer 16324 in area 3491'),
(343316, 1, 3433, 16, 0, 0, 'Windrunner Spire', 'Windrunner Spire was the family seat of the Windrunners and the original home of Sylvanas Windrunner, once ranger-general of Quel''Thalas and now queen of the Forsaken. The mindless Scourge hold it today. Deatholme acolytes and the risen bodies of fallen rangers walk its grounds, cultists and dead elves defiling the house of the woman who once led her homeland''s defense. The Forsaken of Tranquillien count its recapture an honor. Among the undead there, a shimmering necklace engraved for the Lady has turned up, a gift from her sister Alleria that the gloom of the Ghostlands never dimmed.', 'quest 9173 description (original home of Sylvanas, queen of the Forsaken and former ranger-general; overrun by mindless Scourge; an honor; Deatholme Acolytes and Fallen Rangers); quests 9175, 9180 (necklace, inscription, gift from Alleria, does not succumb to the gloom); creature_loot_template: item 22597 drops from 16314 Fallen Ranger and 16315 Deatholme Acolyte; warcraft.wiki.gg/wiki/Windrunner_Spire (Windrunner family home; Deatholme cult); warcraft.wiki.gg/wiki/Ghostlands (Sylvanas and the Farstriders fought the Scourge advance)'),
(343317, 1, 3433, 17, 0, 0, 'Deatholme', 'Deatholme is the Scourge citadel in the southwest of the Ghostlands, where the Dead Scar begins. From the Tower of the Damned at its heart Dar''Khan Drathir rules the undead of the region, served by four lieutenants: Masophet the Black, Jurion the Deceiver, Borgoth the Bloodletter and Mirdoran the Fallen. Nerubian centurions, wailers and eyes of Dar''Khan guard its paths, and the fortress has only one way in or out. Prisoners taken here are tortured under will-breaking poisons. Near the tower lies the body of Blood Knight Dawnstar, who led a failed assault, and a Scourge creature called Dr. Whitherlimb roams the area, harvesting fresh parts and organs for his abominations.', 'warcraft.wiki.gg/wiki/Deatholme (Scourge citadel at the start of the Dead Scar; Tower of the Damned; Dawnstar''s failed assault); quest 9167 description (Scourge stronghold south of the Dead Scar); quest 9170 description (four lieutenants); quest 9220 description (Eyes of Dar''Khan, Nerubis Centurions, Wailers); creature_text 16252 (Deatholme has only one way in and out); quest 9877 description (prisoners tortured under will-breaking poisons); gossip 7486 (Blood Knight Dawnstar, leader of the failed assault); creature_text 22062 (fresh parts; organs; brain for one of my abominations); Dr. Whitherlimb rare spawns in 3500, 3501, 3502'),
(343318, 1, 3433, 18, 0, 0, 'Hatchet Hills and the Amani Pass', 'In the eastern Ghostlands the land climbs through the Hatchet Hills toward the Amani Pass, the gateway to the troll city of Zul''Aman. At the foot of the pass the treasure hunter Budd Nedreck has pitched his camp, complete with a flight master, provisioners and a crew of hangers-on, while the corpses of troll catlords and hexxers lie scattered around it. Budd''s own bodyguards hold the road up into the pass. Not everyone in the camp is what they seem: one of its members, Donna Brascoe, is secretly an agent of the Shattrath Peacekeepers, sent to watch the operation from within.', 'quest 11132 log text (Budd Nedreck in Hatchet Hills); quest 11178 (camp outside Zul''Aman); quest 11163 description (Donna sent by the Shattrath Peacekeepers to infiltrate Budd''s gang); zone_areas: Budd Nedreck, Kiz Coilspanner (flight master), Provisioner Ameenah, Kurzel, Mack, Prigmon, Catlord Corpse 23705, Hexxer Corpse 23716 in 3507; Budd''s Bodyguard 25145 in 3507 and 3508; warcraft.wiki.gg/wiki/Budd_Nedreck (camp in Hatchet Hills just outside Zul''Aman)'),
(343319, 2, 3433, 1, 0, 0, 'Dar''Khan Drathir', 'Dar''Khan Drathir was a magister of Quel''Thalas who spent long nights in Dawnstar Spire and came to despise his own people. When Arthas marched north, Dar''Khan pledged himself to the Scourge, helped it slip past the kingdom''s defenses and plotted to steal the power of the Sunwell for his new masters. The death knight later slew him, yet he has returned from the dead, and from the Tower of the Damned in Deatholme he now commands the Scourge of the Ghostlands. To his masters he promised two elven treasures, the stones of light and flame, charged with the power of the Sunwell. Lady Sylvanas has her own history with him and wants him dead as much as the elves do.', 'warcraft.wiki.gg/wiki/Dar''Khan_Drathir (helped Arthas slip through Thalassian defenses; killed by the death knight per Arthas: Rise of the Lich King); quests 9161, 9162 (scheming against his own; plan to steal the power of the Sunwell for the Scourge); quest 9176 description (promised the Scourge the stones of light and flame); quest 9327 reward text (Sylvanas has a history with Dar''Khan and wants him dead); quest 9167 description; creature 16329 spawns once in Deatholme (faction 16, hostile to both factions)'),
(343320, 2, 3433, 2, 2, 0, 'High Executor Mavren', 'High Executor Mavren commands the Forsaken at Tranquillien. Lady Sylvanas appointed him to help the blood elves destroy Dar''Khan because he has fought the Scourge before, and he never lets anyone forget it. In the tower on the town''s west side he argues his case to Dame Auriferous again and again: Deatholme has only one way in and out, the villages and the trolls are distractions, and a single focused blow at the Tower of the Damned would bring down the rest of the Scourge like a body without its head. He admits that the Undercity is stretched thin and can spare few more. The Forsaken, he says, are the reinforcements.', 'warcraft.wiki.gg/wiki/High_Executor_Mavren (appointed by Sylvanas to assist Auriferous because he had fought the Scourge); creature_text 16252 (all groups: you have not fought the Scourge as I have; one way in and out; head and body; Undercity stretched thin; we are the reinforcements); quest 9327 description (tower on the west side of town)'),
(343321, 2, 3433, 3, 2, 0, 'Dame Auriferous', 'Dame Auriferous governs Tranquillien for Silvermoon, grateful for her Forsaken allies yet impatient for the soldiers their Lady promised. She refuses to throw blood elf lives away on a headlong assault. Her plan is to reclaim the surrounding villages first and cut Deatholme off from reinforcement, for she will not march on Dar''Khan with Shadowpine trolls arrayed along her eastern border and enemies at her back. Advisor Valwyn whispers counsel in her ear and warns visitors that an audience may mean a long wait, and even in a war zone the dame expects the chef she brought from Silvermoon to serve her meals with a proper crunch.', 'creature_text 16231 (all groups: villages first; lives are blood elf; Your Lady promised us more soldiers; Shadowpine and Zul''Aman on the eastern border; Deatholme must come last); gossip 16231 (welcome, Forsaken assistance); creature_text 16289 and gossip 16289 Advisor Valwyn (whispers in the Dame''s ear; seek an audience, long wait); quest 9171 description (chef brought from Silvermoon; Dame Auriferous prefers a crunchy texture)'),
(343322, 2, 3433, 4, 2, 0, 'Arcanist Vandril', 'Arcanist Vandril directs the fight against the Scourge from Tranquillien, and he has learned through hard experience that the undead can only be beaten back in small steps, since every defender who falls may rise again in their ranks. He sends volunteers to retake Suncrown, Goldenmist and Windrunner villages one after another, and apologizes when his scouts miss a danger, for his people are spread too thin. When a courier at last brought him a letter from Regent Lord Lor''themar Theron warning of a dark presence in the Ghostlands, Vandril could only remark that he might have told the regent that himself.', 'quest 9139 request text (beaten back in small steps; they add your fallen to their ranks); quests 9138, 9139, 9140 (the three villages); quest 9315 reward text (shoddy intelligence; spread too thin); quest 9148 description and reward text (letter from Regent Lord Theron; dark presence; I could have told him that); gossip 16197'),
(343323, 2, 3433, 5, 2, 0, 'Magister Kaendris', 'Magister Kaendris leads the magisters of the Sanctum of the Sun. He holds that the Ghostlands will not be won back by military force alone, and that the guile and arcane learning of his order will tip the balance. While his colleague Idonis frets at the delay, Kaendris waits on what the Farstriders have uncovered. When Dar''Khan''s own journal reaches him, he knows the traitor''s handwriting at once and turns its secrets into the means of the traitor''s undoing: the stones of light and flame, through which Dar''Khan can be destroyed by the very power he sought to steal.', 'gossip 16239 (not by military force alone; guile and knowledge of the arcane); creature_text 16204, 16240 (Idonis asks why Kaendris waits; he thinks the Farstriders have uncovered something); quests 9172, 9176 reward texts (Dar''Khan''s handwriting; stones used to vanquish him with the power he sought to steal); quest 9167 (Kaendris sends the champion to slay Dar''Khan); warcraft.wiki.gg/wiki/Sanctum_of_the_Sun (Kaendris leads)'),
(343324, 2, 3433, 6, 2, 0, 'Captain Helios', 'Captain Helios commands the Farstriders at their enclave on Lake Elrendar, and for now his war is with the Shadowpine trolls rather than the Scourge. He means to cut their numbers down and break them before turning toward Deatholme, and he has put a price on the head of their chieftain, Kel''gash the Wicked. The campaign has cost him dearly. He trusted Lieutenant Tomathren to lead the attack on Zeb''Sora and admits he badly overestimated the man, and Ranger Salissa, sent south to beg for help, never arrived. He is quick to thank those who bring his rangers home alive.', 'quest 9214 description and reward text (reduce Shadowpine numbers before shifting attention to Deatholme); quest 9215 (bounty on Kel''gash paid by Captain Helios); quest 9146 reward text (overestimated Tomathren; never heard from Ranger Salissa); quest 9212 reward text and creature_text 16220 (thanks for bringing Lilatha back); warcraft.wiki.gg/wiki/Farstrider_Enclave (Captain Helios leads)'),
(343325, 2, 3433, 7, 2, 0, 'Ranger Valanna and Lieutenant Tomathren', 'On the shore of Lake Elrendar wait the survivors of a disastrous Farstrider expedition. Lieutenant Tomathren rushed his rangers into battle with the trolls of Zeb''Sora without scouting first, and many died. He has since come apart, insisting it was not his fault, expecting a commendation one moment and mistaking the lakeshore for Silvermoon the next. Ranger Valanna, badly wounded, is left to nursemaid him. She sent two rangers running for help, one to Tranquillien and one to the Farstrider Enclave, and while she waits she trades insults with her commander and asks for troll ears to string into a necklace in revenge.', 'quest 9143 description (rushed into battle without scouting; nursemaid him; ears for a necklace; revenge); quest 9145 description (Valanna badly injured; lieutenant fell to pieces; Lethvalin and Salissa sent for help); gossip 16217 (It''s not my fault; I just want to go home to Silvermoon); creature_text 16217 and 16219 (commendation; where are we; insults)'),
(343326, 2, 3433, 8, 2, 0, 'Geranis Whitemorn', 'Geranis Whitemorn was one of the people of Suncrown Village and lingers on a small island in Lake Elrendar, one of its restless dead. Each year the villagers held a rite to bind the water elemental Aquantion as a sign of their dominion over nature, but Aquantion called on the lowly murlocs to sabotage the ritual, turned the villagers'' own magic against them and enslaved their spirits. Geranis seeks the wave-shaped medallions the celebrants once wore, now lost on the lake bed, so that Aquantion can be summoned again at the Altar of Tidal Mastery and destroyed, and the drowned of Suncrown may finally rest.', 'quest 9157 description and reward text (we, the denizens of Suncrown Village; ritual; Aquantion enslaved us; wave medallions at the bottom of the lake; our deaths will be avenged); quest 9174 description and reward text (murlocs sabotaged the rites; Altar of Tidal Mastery; so we may rest); gossip 16201; creature 16201 spawn by the lake (area 3433 near Lake Elrendar); warcraft.wiki.gg/wiki/Geranis_Whitemorn (ghost; killed in Aquantion''s attack; small island in Lake Elrendar)'),
(343327, 2, 3433, 9, 0, 0, 'Kel''gash the Wicked', 'Kel''gash the Wicked is chieftain of the Shadowpine, the forest trolls whose camps fill the eastern Ghostlands. He dwells in Zeb''Nowa, the tribe''s camp astride the road to Zul''Aman, where his catlords and hexxers live, and his warriors cut down many Farstriders at Zeb''Sora while Shadowpine oracles raise the mummified dead of the Amani Catacombs. Captain Helios has posted a wanted notice promising a reward for the chieftain''s head, though no advances, and the rangers believe that with Kel''gash dead the Shadowpine will fall into disarray.', 'quest 9215 description and reward text (chieftain of the Shadowpine; dwells in Zeb''Nowa; no advances; disarray); quests 9275, 9277 (Zeb''Nowa on the road to Zul''Aman; catlords and hexxers); quest 9199 reward text (oracles raising mummies); creature 16358 spawn in area 3517 (faction 1643, hostile to both factions)'),
(343328, 2, 3433, 10, 0, 0, 'Budd Nedreck', 'Budd Nedreck is a human adventurer, a famous one by his own account, who has made camp in the Hatchet Hills at the very gates of Zul''Aman. His inscrutable theories, he insists, confirm rumors of vast treasure within the troll city, with mounts and mansions for everyone. Budd prefers that others take the risks. The recruits he lent his precious map to vanished while hunting the troll beast Nalorakk, so he sends newcomers in wearing his hand-crafted disguises to finish the job, and even to face the Hex Lord Malacrass. He is generous with promises and far stingier with credit, most of which he keeps for himself.', 'quest 11132 description (inscrutable theories, vast treasure, mounts and mansions, map lent to recruits, Nalorakk); quest 11166 description and request text (hand-crafted disguises); quest 11171 description and reward text (Hex Lord Malacrass; dismisses the hero); quest 11178 reward text (claims he could have taken Zul''jin with ease); gossip 8775 (I can only assume that you know who I am); warcraft.wiki.gg/wiki/Budd_Nedreck (human; camp in Hatchet Hills; took the glory for himself)'),
(343329, 3, 3433, 1, 2, 0, 'A Letter for Tranquillien', 'The road into the Ghostlands begins with a missing messenger. Courier Dawnstrider was sent into the Ghostlands on a secret errand and never returned, and his aunt, fearing that the magisters of Silvermoon would not trouble themselves over one lost courier, begged a stranger to look for him. He was found by the road near the bridge over the Elrendar River, collapsed and sickening with plague, and Apothecary Thedra saved him with a serum distilled from the blood of plagued beasts across the river. Too weak to go on, the courier handed over his burden: a letter from Regent Lord Lor''themar Theron to Arcanist Vandril in Tranquillien. After weeks of waiting the town had its answer from the capital at last. The regent sensed a dark presence in the Ghostlands, which, Vandril observed dryly, nobody in Tranquillien needed to be told.', 'quests 9144, 9147, 9148 (descriptions, request and reward texts); creature_queststarter: 16210 Magistrix Landra Dawnstrider starts 9144, 16196 Thedra starts 9147, 16183 Courier Dawnstrider starts 9148'),
(343330, 3, 3433, 2, 2, 0, 'The Forsaken and the Three Villages', 'Tranquillien''s newest allies are walking corpses. The Forsaken of Lady Sylvanas Windrunner, herself born in these lands, have come to the Ghostlands because they share an enemy with the blood elves: Dar''Khan the traitor. Their commander, High Executor Mavren, assures newcomers that his people mean the sin''dorei no harm. The partnership is not an easy one. Mavren would strike straight at Deatholme, while Dame Auriferous insists on first reclaiming the outlying villages to choke off the Scourge''s reinforcements, and the final decision is hers. So Arcanist Vandril sends volunteers northeast to Suncrown Village to break the nerubians and their unexpected leader Anok''suten, then northwest to free Goldenmist from the ghosts of its own people, and at last southwest to Windrunner Village and its shades and gargoyles. With all three villages freed, Tranquillien can turn its strength toward the Dead Scar and Deatholme.', 'quests 9327, 9329 (descriptions and reward texts); quests 9758, 9138, 9139, 9140, 9315 (descriptions and reward texts); creature_text 16231 and 16252 (the strategic argument; the final decision is mine)'),
(343331, 3, 3433, 3, 2, 0, 'Eyes Upon the Sin''dorei', 'Not every intruder in the Ghostlands serves the Scourge. Dame Auriferous learned that night elves had seized an island off the coast and set up camp at An''daroth, an old high elf ley-line nexus, and she wanted to know why. At An''daroth there were only Sentinel spies and strange objects like small, magically grown trees crowned with glowing orbs. A raid on Shalandis Isle and the night elf ship anchored there yielded their plans, which named a second nexus at An''owyn. The plans went to Magister Sylastor, studying the third nexus at An''telas, who had only just driven off a night elf party of his own. Reading them, he understood: the orbs were moon crystals, scrying devices that would let the night elves watch every move the sin''dorei made. With a controlling orb taken from the infiltrators, the crystal at An''owyn was shut down.', 'quests 9160, 9163, 9166, 9169 (descriptions and reward texts); gameobjects 181138, 181139, 181140 (night elf plans on Shalandis Isle); zone_areas: Darnassian Druid and Huntress in area 3503 Shalandis Isle'),
(343332, 3, 3433, 4, 2, 0, 'The Shadowpine War', 'The Farstriders of Lake Elrendar fight a war of their own against the Shadowpine trolls, who are backed by the might of Zul''Aman and hold the forest along Quel''Thalas''s eastern border. It began badly. An attack on Zeb''Sora under Lieutenant Tomathren was launched without scouting, and many rangers died. Since then Captain Helios has kept the trolls off balance, sending volunteers to thin the headhunters and shadowcasters of Zeb''Tela and the catlords and hexxers of Zeb''Nowa, and to bring back their weapons for use against the Scourge. An apothecary on loan from Tranquillien laces the trolls'' food stores with poison, and their chieftain, Kel''gash the Wicked, has a price on his head. Inside Sungraze Peak, Shadowpine oracles raise the mummified dead of the Amani Catacombs, and Tranquillien orders the remains burned. Only when the trolls are broken, the rangers say, can they turn toward Deatholme.', 'quests 9143, 9145, 9146 (Zeb''Sora disaster); quests 9214, 9215, 9275, 9276, 9277 (descriptions and reward texts); quests 9193, 9199, 9212 (catacombs, juju, Lilatha); gossip 16463 (backed by the might of Zul''Aman); creature_text 16231 (Shadowpine and Zul''Aman arrayed across our eastern border)'),
(343333, 3, 3433, 5, 2, 0, 'The Traitor''s Destruction', 'With its surroundings secured, Tranquillien carried the war south. From the rebuilt Sanctum of the Sun, Magister Idonis sent volunteers into Deatholme to thin its nerubians, wailers and eyes of Dar''Khan, and then to slay the traitor''s four lieutenants, while Arcanist Janeda arranged the rescue of prisoners drugged into a stupor, using a restorative draught from Tranquillien''s apothecary. Meanwhile the Farstriders turned up a deeper secret. In Dawnstar Spire lay Dar''Khan''s journal, and in it the tale of two elven artifacts, the stone of light and the stone of flame, taken to where the twin ziggurats now stand on the Dead Scar. Magister Kaendris had them recovered, for their Sunwell energies could be turned against the Scourge. Armed with the very power the traitor had tried to steal, a champion entered Deatholme and slew Dar''Khan, and his head was carried to Lor''themar Theron in Silvermoon, who called it good news in more ways than one could imagine.', 'quests 9151, 9220, 9170, 9877, 9164 (descriptions and reward texts); quests 9161, 9162, 9172, 9282, 9176, 9167 (descriptions and reward texts); quests 9328, 9811 reward texts (Lor''themar: good news in more ways than you can imagine)');
